<script setup lang="ts">
import {musicThemes,musicForVehicle} from "~/data/music"
const state=useAtelier(),audio=useAudio(),{t,language}=useLocale(),settings=ref(false),musicOpen=ref(false)
const frameStats=useState('scene-performance',()=>({fps:0,renderMs:0,drawCalls:0,triangles:0,pixelRatio:0,visible:false}))
function openSettings(){state.graphicsPrompt.value=false;musicOpen.value=false;settings.value=true}
function openMusic(){state.graphicsPrompt.value=false;settings.value=false;musicOpen.value=true}
function toggleGraphics(){settings.value=false;musicOpen.value=false;state.graphicsPrompt.value=!state.graphicsPrompt.value}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}
</script>
<template>
 <header class="header"><NuxtLink to="/" class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></NuxtLink><nav><NuxtLink to="/">{{t('Обзор','Experience')}}</NuxtLink><NuxtLink to="/garage">{{t('Гараж','Garage')}} <sup>08</sup></NuxtLink><NuxtLink :to="'/drive/'+state.car.value.id">{{t('В движении','In motion')}}</NuxtLink><NuxtLink to="/legal">{{t('Лицензии','Licenses')}}</NuxtLink></nav><div class="header-tools">
 <output class="live-fps" aria-live="off" :aria-label="t('Текущий FPS','Current FPS')"><span>{{frameStats.visible?frameStats.fps:'—'}}</span><small>FPS</small></output>
