 <AtelierDialog v-if="settings" class="preferences-dialog" @close="settings=false"><small>VELOCITY 3 / {{t('ПАРАМЕТРЫ','PREFERENCES')}}</small><h2>{{t('Настройки','Settings')}}</h2><div class="preference-list">
